import{_ as t,o,c as d,a0 as a}from"./chunks/framework.Obqu-B4P.js";const u=JSON.parse('{"title":"Audit events","description":"","frontmatter":{},"headers":[],"relativePath":"reference/audit-events.md","filePath":"reference/audit-events.md"}'),r={name:"reference/audit-events.md"};function s(i,e,c,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="audit-events" tabindex="-1">Audit events <a class="header-anchor" href="#audit-events" aria-label="Permalink to &quot;Audit events&quot;">​</a></h1><p>The audit wire: one ndjson line on <strong>stderr</strong> per op outcome, plus an OTLP span per event when <code>OTEL_EXPORTER_OTLP_ENDPOINT</code> is set. cuora keeps no local ledger (ADR-0001 — aggregation is peregrin&#39;s); the stderr stream <em>is</em> the human contract and the OTLP stream the machine one, so a wrapper — peregrin, sepia, your own harness — can capture either, and a human sees a breadcrumb.</p><h2 id="shape" tabindex="-1">Shape <a class="header-anchor" href="#shape" aria-label="Permalink to &quot;Shape&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-01-01T00:00:00Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;actor&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;devin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;run&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rref&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;billing/stripe&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;outcome&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>field</th><th>notes</th></tr></thead><tbody><tr><td><code>ts</code></td><td>RFC 3339, UTC</td></tr><tr><td><code>actor</code></td><td><code>--actor</code> → <code>CUORA_ACTOR</code> → <code>$USER</code>/<code>$LOGNAME</code> → <code>anon</code>. Self-claimed — attribution, not identity</td></tr><tr><td><code>op</code></td><td>the verb: <code>init put get list rm rotate run env check deploy ui serve manifest schema</code></td></tr><tr><td><code>rref</code></td><td>the resolved ref path, env pin stripped — same on <code>denied</code>/<code>error</code> when the arg parses, else the raw arg verbatim. <strong>Absent</strong> on op-scoped events</td></tr><tr><td><code>env</code></td><td>the env the op ran under</td></tr><tr><td><code>outcome</code></td><td><code>ok</code> | <code>denied</code> | <code>error</code></td></tr><tr><td><code>policy</code></td><td><strong>serve-path only, optional</strong> — the PDP verdict <code>{allow, reason?, obligations?}</code> behind the outcome; absent on every other path</td></tr></tbody></table><h2 id="when-events-fire" tabindex="-1">When events fire <a class="header-anchor" href="#when-events-fire" aria-label="Permalink to &quot;When events fire&quot;">​</a></h2><table tabindex="0"><thead><tr><th>event</th><th>meaning</th></tr></thead><tbody><tr><td><code>ok</code>, ref-scoped</td><td>one <strong>per ref</strong> materialized or mutated — <code>put</code>, <code>get</code>, <code>rotate</code>, <code>rm</code>, <code>deploy</code>, and per resolved ref inside <code>run</code>/<code>env</code></td></tr><tr><td><code>ok</code>, op-scoped</td><td>ref-less verb completed — <code>init</code>, <code>list</code>, <code>check</code>, <code>ui</code>, <code>serve</code></td></tr><tr><td><code>denied</code></td><td><code>[guardrails]</code> — or a serve-path PDP verdict of <code>allow: false</code> (including fail-closed on an unreachable PDP) — refused the op before it touched the vault; <code>rref</code> is the requested ref (normalized when parseable)</td></tr><tr><td><code>error</code></td><td>the op ran and failed — missing secret, vault i/o, bad ref; a <code>check</code> with findings also audits <code>error</code> (it exits 1); also emitted when config load itself fails (best-effort actor/env from flags + process env)</td></tr></tbody></table><p>Two deliberate silences:</p><ul><li><code>manifest</code>, <code>schema</code>, <code>gen-cli-docs</code> run before config load — pure introspection, no event.</li><li>A <code>run</code> child&#39;s non-zero exit is the <em>child&#39;s</em> outcome — no <code>error</code> event for it. cuora&#39;s own exit code is the child&#39;s.</li></ul><h2 id="serve-and-the-policy-field" tabindex="-1"><code>serve</code> and the <code>policy</code> field <a class="header-anchor" href="#serve-and-the-policy-field" aria-label="Permalink to &quot;`serve` and the `policy` field&quot;">​</a></h2><p><code>cuora serve</code> emits the same events — <code>get</code>/<code>put</code>/<code>rm</code>/<code>rotate</code> requests audit exactly like the CLI verbs, under the request&#39;s claimed <code>actor</code> when it carries one. The PDP consult covers the ops that can materialize — <code>get</code>/<code>put</code>/<code>rm</code>/<code>rotate</code> <em>and</em><code>list</code>/<code>check</code> (record decrypts, vault probes, scoped-token gets) — so a <code>check</code>&#39;s incidental token <code>get</code>s ride the same <code>policy</code>-bearing events. On the serve path only, every event a consulted <code>[serve.pdp]</code> gated gains a <code>policy</code> object — <code>{allow, reason?, obligations?}</code> — so the stream shows the verdict behind the outcome: a PDP allow, a PDP deny (<code>outcome: &quot;denied&quot;</code>, <code>policy.allow: false</code>), or a degraded allow recorded when <code>allow_on_error</code> overrode an unreachable PDP. The <code>serve</code> verb itself closes with one op-scoped <code>ok</code>. See <a href="./serve-protocol.html">the serve protocol</a>.</p><h2 id="ui-and-the-tui" tabindex="-1"><code>ui</code> and the TUI <a class="header-anchor" href="#ui-and-the-tui" aria-label="Permalink to &quot;`ui` and the TUI&quot;">​</a></h2><p><code>cuora ui</code> emits one op-scoped <code>ok</code> when the browser exits cleanly. Inside it, browsing is silent — listing refs and metadata is not a materialization, and <strong>live stderr audit is muted for the whole session</strong> so events can&#39;t splatter over the alternate screen; everything held replays to stderr after the terminal is restored. The <code>r</code>→<code>r</code> reveal goes through the audited <code>get</code> path: a real <code>{&quot;op&quot;:&quot;get&quot;,&quot;rref&quot;:…,&quot;outcome&quot;:&quot;ok&quot;}</code> event per value shown — held like the rest, replayed on exit.</p><h2 id="otlp-export" tabindex="-1">OTLP export <a class="header-anchor" href="#otlp-export" aria-label="Permalink to &quot;OTLP export&quot;">​</a></h2><p>Set <code>OTEL_EXPORTER_OTLP_ENDPOINT</code> (e.g. <code>http://localhost:4318</code>) and every audit event is additionally buffered as an <code>cuora.&lt;op&gt;</code> span — <code>ExportTraceServiceRequest</code> JSON posted to <code>&lt;endpoint&gt;/v1/traces</code> on flush. Span attributes mirror the ndjson fields: <code>cuora.op</code>, <code>cuora.rref</code> (when present), <code>cuora.env</code>, <code>cuora.actor</code>, <code>cuora.outcome</code>, and <code>cuora.policy.*</code> on serve-path events; <code>Outcome::Error</code> marks the span <code>STATUS_CODE_ERROR</code>. <code>service.name</code> comes from <code>OTEL_SERVICE_NAME</code> (default <code>cuora</code>).</p><p>Flush timing: CLI verbs export once at exit; <code>cuora serve</code> flushes per request (it&#39;s long-running); the TUI flushes at exit like any verb.</p><p>Related env vars: <code>OTEL_EXPORTER_OTLP_HEADERS</code> (<code>k=v</code> pairs, percent-decoded), <code>OTEL_EXPORTER_OTLP_TIMEOUT</code> (ms, default 10000), <code>OTEL_SDK_DISABLED=true</code> turns export off entirely, and <code>CUORA_AUDIT_STDERR=0</code> silences the stderr wire (OTLP-only mode).</p><h2 id="failure-posture" tabindex="-1">Failure posture <a class="header-anchor" href="#failure-posture" aria-label="Permalink to &quot;Failure posture&quot;">​</a></h2><p>Audit emission is best-effort on both wires: a closed stderr (broken pipe) never takes the broker down — the write error is swallowed by design — and a failed OTLP export warns once on stderr, never fails the op.</p><p>Note: stderr can also carry non-ndjson <code>cuora:</code> <em>notice</em> lines (permission warnings, keyring fallback notes) — UX chatter, not audit wire. Consumers parsing stderr as pure ndjson should tolerate lines that don&#39;t start with <code>{</code>. During <code>cuora ui</code> both audit events and notices are held and replayed after the terminal is restored.</p><h2 id="granularity" tabindex="-1">Granularity <a class="header-anchor" href="#granularity" aria-label="Permalink to &quot;Granularity&quot;">​</a></h2><p>Per-ref events fire when a value crosses the store boundary toward a caller: <code>get</code>, <code>put</code>, <code>rotate</code>, <code>rm</code>, <code>deploy</code>, <code>run</code>, <code>env</code>, and serve <code>get</code>/<code>put</code>/<code>rotate</code>/<code>rm</code>. Bulk reads — <code>list</code>, <code>check</code>, the TUI reload, serve <code>list</code> — emit <strong>op-scoped</strong> events only: they decrypt records internally to verify or enumerate, but no value is returned to the caller, so there is no per-ref materialization to attribute. If your threat model counts &quot;decrypted in-process&quot; as materialization, treat bulk ops as single events covering N refs — the op name tells you which verb ran, not which refs it touched.</p>',22)])])}const k=t(r,[["render",s]]);export{u as __pageData,k as default};
